input.proposed_solution:
Accept only plain base-10 integers; values below 1 or non-numeric input fall back to the default 20; values above 100 are clamped to 100 (the documented maximum). Exposed DEFAULT_LIMIT and MAX_LIMIT constants. Added tests for capping, garbage, negatives, zero, "12abc", "1e3" and leading zeros.

Patch (already applied in the repository snapshot):
```diff
--- a/src/query.js
+++ b/src/query.js
@@ -1,10 +1,16 @@
 // @ts-check

+export const DEFAULT_LIMIT = 20;
+export const MAX_LIMIT = 100;
+
 /**
- * Parse the ?limit= query parameter.
+ * Parse the ?limit= query parameter: base-10 integer in [1, MAX_LIMIT]; anything else → DEFAULT_LIMIT.
  * @param {string | undefined} raw
  * @returns {number}
  */
 export function parseLimit(raw) {
-  return parseInt(raw ?? "") || 20;
+  if (raw === undefined || !/^\s*\d+\s*$/.test(raw)) return DEFAULT_LIMIT;
+  const n = Number.parseInt(raw, 10);
+  if (n < 1) return DEFAULT_LIMIT;
+  return Math.min(n, MAX_LIMIT);
 }
--- a/test/query.test.js
+++ b/test/query.test.js
@@ -4,3 +4,8 @@

 test("parses numbers", () => assert.equal(parseLimit("50"), 50));
 test("defaults when missing", () => assert.equal(parseLimit(undefined), 20));
+test("caps at 100", () => assert.equal(parseLimit("100000"), 100));
+test("rejects garbage, negatives and zero", () => {
+  for (const raw of ["abc", "-5", "0", "12abc", "1e3", ""]) assert.equal(parseLimit(raw), 20, raw);
+});
+test("base 10 even with leading zeros", () => assert.equal(parseLimit("010"), 10));
```
